MapKitHostApiForNativeInterop? pigeon_getInstance_MapKitHostApi({
  String channelName = defaultInstanceName,
}) => _MapKitHostApiForNativeInterop.getInstance(channelName: channelName);

class _MapKitHostApiForNativeInterop implements MapKitHostApiForNativeInterop {
  _MapKitHostApiForNativeInterop._withRegistrar({
    ffi_bridge.MapKitHostApiSetup? ffiApi,
  }) : _ffiApi = ffiApi;

  /// Returns instance of MapKitHostApiForNativeInterop with specified [channelName] if one has been registered.
  ///
  /// Returns the instance registered by this isolate's engine when it is known,
  /// and otherwise the most recent registration.
  static MapKitHostApiForNativeInterop? getInstance({
    String channelName = defaultInstanceName,
  }) {
    if (Platform.isIOS || Platform.isMacOS) {
      final int? engineId = PlatformDispatcher.instance.engineId;
      final ffi_bridge.MapKitHostApiSetup? link =
          ffi_bridge.MapKitHostApiSetup.pigeonResolveInstanceWithEngineId(
            engineId ?? _pigeonNoEngineKey,
            affinityKey: _pigeonEngineAffinity ?? _pigeonNoEngineKey,
            name: NSString(channelName),
          );
      if (link == null) {
        _throwNoInstanceError(channelName);
      }
      if (link != null && _pigeonEngineAffinity == null) {
        final int linkEngineKey =
            ffi_bridge.MapKitHostApiSetup.pigeonEngineKeyOf(link);
        if (linkEngineKey != _pigeonNoEngineKey &&
            (engineId == null || linkEngineKey < 0)) {
          _pigeonEngineAffinity = linkEngineKey;
          _pigeonUpdateFlutterApiEngineAffinity();
        }
      }
      return _MapKitHostApiForNativeInterop._withRegistrar(ffiApi: link);
    } else {
      throw UnsupportedError(
        'Native Interop is not supported on this platform. Use MapKitHostApi instead.',
      );
    }
  }

  late final ffi_bridge.MapKitHostApiSetup? _ffiApi;

  @override
